file.content:
[
  {
    "id": "c001",
    "name": "Declarations — Insurer",
    "text": "This Policy is issued by the stock insurance company listed above (herein called the Insurer)."
  },
  {
    "id": "c002",
    "name": "Declarations — Claims-Made Coverage",
    "text": "THIS POLICY PROVIDES LIABILITY COVERAGE ON A CLAIMS-MADE AND REPORTED BASIS, WHICH COVERS ONLY CLAIMS FIRST MADE AGAINST THE INSURED AND REPORTED TO THE INSURER, IN WRITING, DURING THE POLICY PERIOD."
  },
  {
    "id": "c003",
    "name": "Declarations — Discovered and Reported Coverage",
    "text": "THIS POLICY PROVIDES COVERAGE FOR REMEDIATION COSTS ON A DISCOVERED AND REPORTED BASIS, WHICH COVERS ONLY POLLUTION CONDITIONS FIRST DISCOVERED AND REPORTED TO THE INSURER, IN WRITING, DURING THE POLICY PERIOD."
  },
  {
    "id": "c004",
    "name": "Declarations — Defense Expenses",
    "text": "DUTIES. LEGAL DEFENSE EXPENSES ARE SUBJECT TO AND SHALL ERODE THE LIMITS OF LIABILITY AND ANY APPLICABLE SELF-INSURED RETENTION."
  },
  {
    "id": "c005",
    "name": "Declarations — Policy Documents",
    "text": "THE DECLARATIONS, TOGETHER WITH THE COMPLETED AND SIGNED APPLICATION, THIS POLICY, AND ANY ENDORSEMENTS OR SCHEDULES ATTACHED HERETO, CONSTITUTE THE INSURANCE POLICY."
  },
  {
    "id": "c006",
    "name": "Item 2.a. Coverage A Policy Period",
    "text": "Item 2, COVERAGE A -— New Pollution Conditions Coverage a, Policy Period Policy Inception Date: Policy Expiration Bate: local time or the acdress November 01, 2014 12:01 A.M. November 01, 2017 12:01 A.M."
  },
  {
    "id": "c007",
    "name": "Item 2.b. Coverage A Per-Condition Limit",
    "text": "b. Limits of Liability per \"pollution condition\" $ 2,000,000"
  },
  {
    "id": "c008",
    "name": "Item 2.c. Coverage A Aggregate Limit",
    "text": "c. Limits of Liability aggregate all “pollution canditions” $ 9,000,000"
  },
  {
    "id": "c009",
    "name": "Item 2.d. Coverage A Retention",
    "text": "d. Self-Insured Retention per | $ 100,000 “pollution condition\""
  },
  {
    "id": "c010",
    "name": "Item 3.a. Coverage B Policy Period",
    "text": "Item 3. COVERAGE B — Pre-Existing Pollution Conditions Coverage a, Policy Period Policy Inception Date: Policy Expiration Date: local fe or the arenes November 01, 2014 12:01 A.M. November 01, 2017 12:01 A.M."
  },
  {
    "id": "c011",
    "name": "Item 3.b. Coverage B Per-Condition Limit",
    "text": "hk. Limits of Liability per | $ 2,000,000 “pollution condition”"
  },
  {
    "id": "c012",
    "name": "Item 3.c. Coverage B Aggregate Limit",
    "text": "c. Limits of Liability sages’ | $ 5,000,000 * , all “pollution conditions”"
  },
  {
    "id": "c013",
    "name": "Item 3.d. Coverage B Retention",
    "text": "d. Self-Insured Retention per | $ 100,000 “pollution condition\""
  },
  {
    "id": "c014",
    "name": "Item 4. Total Policy Aggregate",
    "text": "Item 4. Limits of Liability: Total Policy Aggregate $ 7,000,000"
  },
  {
    "id": "c015",
    "name": "Item 5. Premium",
    "text": "Item 5. Premium: $ 134,651.00 Total Premium: $ 134,651.00 (This premium amount shall be deemed 100 % minimum-earned as of the first day of the Policy Period indicated in Item. 2.a and/or litem, 3.a., above., whichever is earlier.)"
  },
  {
    "id": "c016",
    "name": "Declarations — Currency",
    "text": "All dollar amounts identified above are in United States dollars."
  },
  {
    "id": "c017",
    "name": "General Coverage Agreement",
    "text": "In consideration of the payment of the premium and in reliance upon all statements made in the Application to this Policy, including the information furnished in connection therewith, and subject to all terms, definitions, conditions, exclusions and limitations of this Policy, the Insurer agrees to provide insurance coverage to the “insured” as described herein."
  },
  {
    "id": "c018",
    "name": "I.A. New Pollution Conditions Coverage",
    "text": "I. INSURING AGREEMENTS Solely to the extent that the Coverages, below, are identified on the Declarations to this Policy as being underwritten by the Insurer, the Insurer agrees to pay on behalf of the “insured” for: A. NEW POLLUTION CONDITIONS (Coverage A.) “Claims”, “remediation costs”, and associated “legal defense expenses’, in excess of the “self-insured retention\", arising out of a \"pollution condition” on, at, under, or migrating from a “covered location’, provided the “claim” is first made, or the “insured” first discovers such \"pollution condition”, during the “policy period”. Any such discovery of a “pollution condition” must be reported to the Insurer, in writing, during the “policy period”. Any such “claim” must be reported to the Insurer, in writing, during the “policy period” or any applicable “extended reporting period”."
  },
  {
    "id": "c019",
    "name": "I.A. New Pollution Conditions Timing",
    "text": "The coverage afforded pursuant to this Coverage A. only applies to “pollution conditions” that first commence, in their entirety, during the “policy period’."
  },
  {
    "id": "c020",
    "name": "I.B. Pre-Existing Pollution Conditions Coverage",
    "text": "B. PRE-EXISTING POLLUTION CONDITIONS (Coverage B.) “Claims”, \"remediation costs”, and associated “legal defense expenses”, in excess of the “self-insured retention”, arising out of a “pollution condition” on, at, under, or migrating from a “covered location”, provided the “claim” is first made, or the “insured” first discovers such “pollution condition’, during the “nolicy period”. Any such discovery of a “pollution condition” must be reported to the Insurer, in writing, during the “policy period”. Any such “claim” must be reported to the Insurer, in writing, during the “policy period” or any applicable “extended reporting period”."
  },
  {
    "id": "c021",
    "name": "I.B. Pre-Existing Conditions Timing",
    "text": "The coverage afforded pursuant to this Coverage B. only applies to “pollution conditions” that first commenced, in whole or part, prior to the “policy period”."
  },
  {
    "id": "c022",
    "name": "II.A. Attachment of Insurer Obligation",
    "text": "LIMITS OF LIABILITY AND SELF-INSURED RETENTION A. It is expressly agreed that the insurer's obligation to pay for any covered “claims”, “remediation costs” or “legal defense expense\" pursuant to this Policy shall attach to the Insurer only after the “first named insured” has paid, or has provided evidence to the Insurer that another “named insured” has paid, the full amount of the “self-insured retention\" with respect to any covered “pollution condition\". Under no circumstances shall the Insurer be liable to pay any amount within the “self-insured retention”. In the event that the “first named insured” cannot provide satisfactory evidence that a “named insured” has paid the full amount of the “self-insured retention” with respect to any covered \"pollution condition”, the “first named insured” shall remain responsible to pay the “self-insured retention” before the Insurer's payment obligation pursuant to this Policy shall attach with respect to coverage sought by any “insured”."
  },
  {
    "id": "c023",
    "name": "II.B. One Retention",
    "text": "One “self-insured retention” shall apply to all “claims\", “remediation costs” and “legal defense expenses” arising out of the same, continuous, repeated, or related “pollution condition’."
  },
  {
    "id": "c024",
    "name": "II.C. Coverage A Per-Condition Limit",
    "text": "With respect to Coverage A., and subject to Subsections D., G. and H., below, the most the Insurer shall pay for all “claims”, “remediation costs” and “legal defense expense” arising out of the same, continuous, repeated, or related “poliution condition” is the Limit of Liability identified in Item 2.b. of the Declarations to this Policy."
  },
  {
    "id": "c025",
    "name": "II.D. Coverage A Aggregate Limit",
    "text": "With respect to Coverage A., and subject to Subsection C., above, and Subsections G. and H., below, the Limit of Liability identified in Item 2.c. of the Declarations to this Policy shall be the maximum liability of the Insurer pursuant to this Policy with respect to all “claims”, “remediation costs” and “legal defense expense” for all “pollution conditions”."
  },
  {
    "id": "c026",
    "name": "II.E. Coverage B Per-Condition Limit",
    "text": "With respect to Coverage B., and subject to Subsections F., G. and H., below, the most the Insurer shall pay for all “claims”, “remediation costs” and “legal defense expense” arising out of the same, continuous, repeated, or related “pollution condition” is the Limit of Liability identified in Item 3.b. of the Declarations to this Policy."
  },
  {
    "id": "c027",
    "name": "II.F. Coverage B Aggregate Limit",
    "text": "With respect to Coverage B., and subject to Subsection E., above, and Subsections G. and H., below, the Limit of Liability identified in Item 3.c. of the Declarations to this Policy shall be the maximum liability of the Insurer pursuant to this Policy with respect to all “claims”, “remediation costs” and “legal defense expense” for all “pollution conditions”."
  },
  {
    "id": "c028",
    "name": "II.G. Total Policy Aggregate Limit",
    "text": "Subject to Subsections C., D., E. and F., above, the Total Policy Aggregate Limit of Liability identified in Item 4. of the Declarations to this Policy shall be the maximum liability of the Insurer pursuant to this Policy with respect to all “claims”, “remediation costs” and “legal defense expense” for all “pollution conditions” covered pursuant to Coverages A. and B., and any Supplemental Coverages added by endorsement to this Policy, if any."
  },
  {
    "id": "c029",
    "name": "II.H. Related Conditions and Claims",
    "text": "If the Insurer or an affiliate has issued pollution liability coverage afforded on a discovered and reported basis or claims-made and reported basis consistent with Coverages A. or B., herein, in one or more policy periods, and a “pollution condition’ is first discovered and reported to the Insurer, or a “claim” is first made and reported to the Insurer with respect to a “pollution condition’, in accordance with the terms and conditions of this Policy, then: 1. Any continuous, repeated, or related \"pollution condition” that is subsequently reported to the Insurer during later policy periods shall be deemed to be one “pollution condition” discovered during this “policy period”; and ny ft 2. All “claims” seeking “bodily injury”, “property damage” or “remediation costs\" arising out of: a. That same, continuous, repeated, or related “pollution condition’ that was discovered during this “policy period”; or b. That same, continuous, repeated, or related “pollution condition” that was the subject of a “claim” first made and reported during this “policy period” or any applicable “extended reporting period’, shall be deemed to have been first made and reported during this “policy period” and no other policy shail respond."
  },
  {
    "id": "c030",
    "name": "III.A. Duty to Defend",
    "text": "lil. DEFENSE AND SETTLEMENT A. The Insurer shall have the right and, subject to the “self-insured retention” obligation, the duty to defend the “insured” against a “claim” to which this insurance applies. The Insurer shall have no duty to defend the “insured” against any “claim” to which this insurance does not apply. The Insurer’s duty to defend the “msured” ends once the Limits of Liability are exhausted or are tendered into a court of applicable jurisdiction, or once the “insured” refuses a settlement offer as provided in Subsection E., below."
  },
  {
    "id": "c031",
    "name": "III.B. Selection of Counsel",
    "text": "B. The Insurer shall have the right to select legal counsel to represent the “insured” for the investigation, adjustment, and defense of any “claims” covered pursuant to this Policy. Selection of legal counsel by the Insurer shall not be done without the consent of the “insured”; such consent shall not be unreasonably withheld. “Legal defense expenses” incurred prior to the selection of legal counsel by the Insurer shall not be covered pursuant to this Policy, or credited against the \"self-insured retention”."
  },
  {
    "id": "c032",
    "name": "III.B. Independent Counsel",
    "text": "In the event the “insured” is entitled by law to select independent counsel to defend itself at the Insurer's expense, the attorney fees and all other litigation expenses the insurer shall pay to that counsel are limited to the rates the Insurer actually pays to counsel that the Insurer normally retains in the ordinary course of business when defending “claims” or lawsuits of similar complexity in the jurisdiction where the “claim” arose or is being defended. In addition, the “insured” and the Insurer agree that the Insurer may exercise the right to require that such counsel: 1) have certain minimum qualifications with respect to their competency, inciuding experience in defending “claims” similar to those oeing asserted against the “insured”; 2) maintain suitable errors and omissions insurance coverage; 3) be located within a reasonable proximity to the jurisdiction of the “claim\"; and 4) agree in writing to respond in a timely manner to the Insurer's requests for information regarding the “claim”. The “insured” may at anytime, by its signed consent, freely and fully waive its right to select independent counsel."
  },
  {
    "id": "c033",
    "name": "III.C. Environmental Consultant",
    "text": "C. The “insured” shall have the right and the duty to retain a qualified environmental consultant to perform any investigation and/or remediation of any “pollution condition” covered pursuant to this Policy. The “insured” must receive the written consent of the Insurer prior to the selection and retention of such consultant, except in the event of an “emergency response”. Any costs incurred prior to such consent shall not be covered pursuant to this Policy, or credited against the “self-insured retention’, except in the event of an “emergency response”."
  },
  {
    "id": "c034",
    "name": "III.D. Defense Expenses Erode Limits",
    "text": "D. “Legal defense expenses” reduce the Limits of Liability identified in Items 2., 3. and 4. of the Declarations to this Policy and shall be applied to the “self-insured retention’."
  },
  {
    "id": "c035",
    "name": "III.E. Settlement",
    "text": "E. The Insurer shall present all settlement offers to the “insured”. If the Insurer recommends a settlement which is acceptable to a claimant, exceeds any applicable “self-insured retention”, is within the Limits of Liability, and does not impose any additional unreasonable burdens on the “insured”, and the “insured” refuses to consent to such settlement offer, then the insurer's duty to defend shall end. Thereafter, the “msured” shall defend such “claim” independently and at the “insured’s” own expense. The Insurer's liability shall not exceed the amount for which the “claim” could have been settled if the Insurer's recommendation had been accepted, exclusive of the “self-insured retention’."
  },
  {
    "id": "c036",
    "name": "IV. Coverage Territory",
    "text": "IV. COVERAGE TERRITORY The coverage afforded pursuant to this Policy shall only apply to “pollution conditions\" located, and “claims” made, within the United States of America."
  },
  {
    "id": "c037",
    "name": "V.A. Additional Insured",
    "text": "V. DEFINITIONS A. “Additional insured” means any person or entity specifically endorsed onto this Policy as an “additional insured”, if any. Such ‘additional insured” shall maintain only those rights that are specified by endorsement to this Policy."
  },
  {
    "id": "c038",
    "name": "V.B. Bodily Injury",
    "text": "B. “Bodily injury” means physical injury, illness, disease, mental anguish, emotional distress, or shock, sustained by any person, including death resulting therefrom, and any prospective medical monitoring costs that are intended to confirm any such physical injury, illness or disease."
  },
  {
    "id": "c039",
    "name": "V.C. Certified Industrial Hygienist",
    "text": "C. “Certified industrial hygienist” means a licensed professional, as established by the American Board of Industrial Hygiene, that is: 1. Mutually agreed upon by the Insurer and the \"insured\"; and 2. Qualified by knowledge, skill, education and training to perform an assessment of the fungal or bacterial ecology of a property, building systems and/or contents, prepare an investigation protocol, interpret the results and prepare a scope of work to remediate the site to an ordinary ambient indoor air ecology for similar indoor environments. The Insurer may also exercise the right to require that such “certified industrial hygienist” have certain minimum qualifications with respect to their competency, including experience with similar “fungi” or legionella pneumophila remediation projects."
  },
  {
    "id": "c040",
    "name": "V.D. Claim",
    "text": "D. “Claim” means the written assertion of a legal right received by the “insured” from a third-party, including, but not limited to, a “government action”, suits or other actions alleging responsibility or liability on the part of the “insured” for “bodily injury’, “property damage” or “remediation costs” arising out of “pollution conditions” to which this insurance applies."
  },
  {
    "id": "c041",
    "name": "V.E. Contingent Transportation",
    "text": "E. “Contingent transportation” means the movement of the “insured’s” waste or products by automobile, aircraft, watercraft, railcar or other conveyance beyond the boundaries of a “covered location\" by a person or entity, other than an “insured”, engaged in the business of transporting property for hire, until such time as the waste or product is unloaded from the automobile, aircraft, watercraft, railcar or other conveyance."
  },
  {
    "id": "c042",
    "name": "V.F. Covered Location",
    "text": "F. “Covered location” means: Any location specifically identified in Item 8. of the Declarations to this Policy; 2. Any location that meets the prerequisites to coverage identified in Automatic Acquisition and Due Diligence Endorsement attached to this Policy, if any; and 3. Any other location specifically scheduled as a “covered location” by endorsement attached to this Policy, if any."
  },
  {
    "id": "c043",
    "name": "V.G. Emergency Response",
    "text": "G. “Emergency response” means actions taken and reasonable “remediation costs” incurred within seventy-two (72) hours following the discovery of a \"pollution condition\" by an “insured” in order to abate or respond to an imminent and substantial threat to human health or the environment arising out of such “pollution condition”."
  },
  {
    "id": "c044",
    "name": "V.H. Environmental Indemnity Obligations",
    "text": "H. “Environmental indemnity obligations” means an \"insured's” obligations to defend or indemnify a third-party with respect to a “pollution condition” to which this insurance otherwise applies, provided that such defense or indemnity obligation is explicitly included within a contract identified on the Schedule of Insured Contracts Endorsement attached to this Policy, if any."
  },
  {
    "id": "c045",
    "name": "V.I. Environmental Law",
    "text": "“Environmental Jaw” means any federal, state, provincial, municipal or other local law, statute, ordinance, rule, guidance document, regulation, and all amendments thereto, including state voluntary cleanup or risk-based corrective action guidance, governing the liability or responsibilities of the “insured” with respect to a “pollution condition’."
  },
  {
    "id": "c046",
    "name": "V.J. Extended Reporting Period",
    "text": "J. “Extended reporting period” means the additional period of time in which to report a “claim” first made against the “insured” during or subsequent to the end of the “policy period”."
  },
  {
    "id": "c047",
    "name": "V.K. First Named Insured",
    "text": "K. “First named insured” means the person or entity as identified in Item 1. of the Declarations to this Policy. The “first named insured” is the party responsible for the payment of any premiums and the payment of, or evidencing payment of, any applicable “self-insured retention” amounts. The “first named insured” shall also serve as the sole agent on behalf of all “insureds” with respect to the provision and receipt of notices, including notice of cancellation or non-renewal, receipt and acceptance of any endorsements or any other changes to this Policy, return of any premium, assignment of any interest pursuant to this Policy, as well as the exercise of any applicable “extended reporting period”, unless any such responsibilities are otherwise designated by endorsement."
  },
  {
    "id": "c048",
    "name": "V.L. Fungi",
    "text": "L. “Fungi” means any type or form of fungus, including mold or mildew, and any mycotoxins, spores, scents, or byproducts produced or released by “fungi”."
  },
  {
    "id": "c049",
    "name": "V.M. Government Action",
    "text": "M. “Government action” means action taken or liability imposed by any federal, state, provincial, municipal or other local government agency or body acting pursuant to the authority of “environmental law”,"
  },
  {
    "id": "c050",
    "name": "V.N. Illicit Abandonment",
    "text": "N. “Hlicit abandonment” means the intentional placement, abandonment or disposal of any solid, liquid, gaseous or thermal irritant, contaminant, or pollutant, including smoke, soot, vapors, fumes, acids, alkalis, chemicals, hazardous substances, hazardous materials, or waste materials, including “low-level radioactive waste”, “mixed waste” and medical, infectious and pathological wastes, on, at or into a “covered location” by a person or entity that: 1. Is not an “insured”; 2. is not affiliated by common ownership with an \"insured\", and 3. Does not maintain, or has not maintained, an ownership or operational interest in the “covered location”."
  },
  {
    "id": "c051",
    "name": "V.O. Insured",
    "text": "0. “Insured” means the \"first named insured”, any “named insured”, any “additional insured”, and any past or present director or officer of, partner in, employee of, temporary or leased worker of, or, with respect to a limited liability company, a member of, any “insured” while acting within the scope of his or her duties as such,"
  },
  {
    "id": "c052",
    "name": "V.P. Legal Defense Expense",
    "text": "P. “Legal defense expense” means reasonable legal costs, charges, and expenses, including expert charges, incurred by the “insured” in the investigation, adjustment, or defense of “claims”."
  },
  {
    "id": "c053",
    "name": "V.Q. Low-Level Radioactive Waste",
    "text": "Q. “Low-level radioactive waste” means waste that is radioactive but not classified as the following: highlevel waste (spent nuclear fuel or the highly radioactive waste produced if spent fuel is reprocessed), uranium milling residues, and waste with greater than specified quantities of elements heavier than uranium."
  },
  {
    "id": "c054",
    "name": "V.R. Mixed Waste",
    "text": "R. “Mixed waste” means waste containing both radioactive and hazardous components as defined pursuant to United States law within the Atomic Energy Act and the Resource Conservation and Recovery Act as either may be amended."
  },
  {
    "id": "c055",
    "name": "V.S. Named Insured",
    "text": "S. “Named insured” means any person or entity specifically endorsed onto this Policy as a “named insured”, if any. Such “named insured” shall maintain the same rights pursuant to this Policy as the “first named insured\", except for those rights specifically reserved to the “first named insured” that are identified in Subsection K., above."
  },
  {
    "id": "c056",
    "name": "V.T. Natural Resource Damage",
    "text": "T. “Natural resource damage” means injury to, destruction of, or loss of, including the resulting loss of value of, fish, wildlife, biota, land, air, water, groundwater, drinking water supplies, and other such resources belonging to, managed by, held in trust by, appertaining to, or otherwise controlled by the United States of America (including the resources of the fishery conservation zone established by the Magnuson-Stevens Fishery Conservation and Management Act (16 U.S.C. § 1801 et. seq.)), any state or local government, or any Native American Tribe, or, if such resources are subject to a trust restriction on alienation, any members of any Native American Tribe, including the reasonable costs of assessing such injury, destruction or loss resulting therefrom."
  },
  {
    "id": "c057",
    "name": "V.U. Non-Owned Disposal Site",
    "text": "U. “Non-owned disposal site” means any disposal site or recycling facility not owned or operated by an “insured”, which receives, or has historically received, an “insured’s\" waste."
  },
  {
    "id": "c058",
    "name": "V.V. Policy Period",
    "text": "V. “Policy period” means: 1. The period of time specifically identified in Item 2.a. of the Declarations to this Policy for Coverage A. and/or Item 3.a. of the Declarations to this Policy for Coverage B.; 2. With respect to “covered locations” added pursuant to the Automatic Acquisition and Due Diligence Endorsement attached to this Policy, if any, the period of time following the closing date of the acquisition transaction or the effective date of the lease or, as applicable, through the applicable expiration date of the Policy identified in Item 2.a. or 3.a. of the Declarations to this Policy with respect to New Poilution Conditions Coverage and Pre-Existing Pollution Conditions Coverage, respectively; or 3. Any shorter period resulting from the cancellation of this Policy."
  },
  {
    "id": "c059",
    "name": "V.W. Pollution Condition",
    "text": "W. “Pollution condition” means: 1. The presence of “fungi” or /egionella pneumophila; 2. “Illicit abandonment”: or 3. The discharge, dispersal, release, escape, migration or seepage of any solid, liquid, gaseous or thermal irritant, contaminant, or pollutant, including smoke, soot, vapors, fumes, acids, alkalis, chemicals, hazardous substances, hazardous materiais, or waste materials, on, in, into, or upon land and structures thereupon, the atmosphere, surface water, or groundwater. For the purpose of this definition, waste materials include, but are not limited to, “low-level radioactive waste” and “mixed waste”."
  },
  {
    "id": "c060",
    "name": "V.X. Property Damage",
    "text": "X. “Property damage” means: 1. Physical injury to, or destruction of, tangible property of a third-party, including all resulting loss of use of that property; 2. Loss of use of tangible property of a third-party, that is not physically injured or destroyed; 3. Diminished value of tangible property owned by a third-party; or 4. “Natural resource damages’."
  },
  {
    "id": "c061",
    "name": "V.Y. Remediation Costs",
    "text": "Y. “Remediation costs” means reasonable expenses incurred to investigate, quantify, monitor, mitigate, abate, remove, dispose, treat, neutralize, or immobilize “pollution conditions” to the extent required by “environmental law\". If no applicable laws exist that govern the remediation of “fungi” or /egionella pneumophila in the jurisdiction of the “covered location’, necessary “remediation costs” may be established by securing the written professional recommendations of a “certified industrial hygienist” retained with the prior approval of the Insurer. “Remediation costs” shall also include: 1. Reasonable legal cost, where such cost has been incurred by an “insured” with the written consent of the Insurer; and 2. Reasonable expenses required to restore, repair or replace real or personal property, to substantially the same condition it was in prior to being damaged during the course of responding to a “pollution condition”."
  },
  {
    "id": "c062",
    "name": "V.Z. Responsible Person",
    "text": "Z. “Responsible person” means any employee of an “insured” responsible for environmental affairs, control, or compliance at a “covered location”, and any officer or director of, or partner in, an “insured”."
  },
  {
    "id": "c063",
    "name": "V.AA. Self-Insured Retention",
    "text": "AA.“Self-insured retention” means the dollar amount identified in Item 2.d. of the Declarations to this Policy for Coverage A. and/or Item 3.d. of the Declarations to this Policy for Coverage B., or as otherwise designated by endorsement to this Policy, if any."
  },
  {
    "id": "c064",
    "name": "V.BB. Terrorism",
    "text": "BB.\"“Terrorism” means activities against persons, organizations or property of any nature: 1. That involve the following or preparation for the following: a. Use or threat of force or violence; or b. Commission or threat of a dangerous act; or c. Commission or threat of an act that interferes with or disrupts an electronic, communication, information, or mechanical system; and 2. When one or both of the following applies: @ 2010 re Page 6 of 13 a. The effect is to intimidate or coerce a government or the civilian population or any segment thereof, orto disrupt any segment of the economy; or b. It appears that the intent is to intimidate or coerce a government, or to further political, ideological, religious, social or economic objectives or to express (or express opposition to) a philosophy or ideology."
  },
  {
    "id": "c065",
    "name": "V.CC. Underground Storage Tank",
    "text": "CC.“Underground storage tank” means any tank and associated piping and appurtenances connected thereto which tank has more than ten percent (10%) of its volume below ground. “Underground storage tank” does not mean a septic tank or oil/water separator."
  },
  {
    "id": "c066",
